      '</div>';
    h += '<p class="dar-source-line">النص: المصحف العثماني (quran-uthmani) • الصوت: تسجيل ' + darEsc(darReciterName()) + ' • التفسير: التفسير الميسر — مجمع الملك فهد لطباعة المصحف الشريف</p>';
    host.innerHTML = h;
