/* ---------- HADITH ---------- */
let darHadithColl = 'bukhari';
let darHadithBook = null;   // book object
let darHadithPage = 0;      // 0-based page of 10
const DAR_HADITH_PAGE = 10;

function darRenderHadith() {
  const host = darEl('hadithContent');
  if (!host) return;
  let h = '<div class="dar-section-intro"><h3 class="dar-h3">الحديث النبوي الشريف</h3>' +
    '<p>من صحيح البخاري وصحيح مسلم — النص كما هو في المصدر الموثّق، مع رقم الكتاب والحديث. لا يُكتب أي حديث من الذاكرة.</p></div>';
  h += '<div class="dar-coll-tabs">' +
    '<button class="dar-coll-tab' + (darHadithColl === 'bukhari' ? ' active' : '') + '" onclick="darSetHadithColl(\'bukhari\')">صحيح البخاري</button>' +
    '<button class="dar-coll-tab' + (darHadithColl === 'muslim' ? ' active' : '') + '" onclick="darSetHadithColl(\'muslim\')">صحيح مسلم</button></div>';
  h += '<div id="darHadithBody"></div>';
  host.innerHTML = h;
  darRenderHadithBody();
}
function darSetHadithColl(c) {
  darHadithColl = c; darHadithBook = null; darHadithPage = 0;
  darRenderHadith();
}
function darRenderHadithBody() {
  const body = darEl('darHadithBody');
  if (!body) return;
  const coll = DAR_HADITH[darHadithColl];
  if (!darHadithBook) {
    let h = '<div class="dar-search"><input type="search" placeholder="ابحث عن كتاب… (مثال: الصلاة)" oninput="darFilterHadithBooks(this.value)"></div>';
    h += '<div class="dar-book-grid" id="darBookGrid">';
    coll.books.forEach(function (b) {
      h += '<button class="dar-book-card" data-name="' + darEsc(b.name) + '" onclick="darOpenHadithBook(' + b.n + ')">' +
        '<span class="dar-book-name">كتاب ' + darEsc(b.name) + '</span>' +
        '<span class="dar-book-meta">' + b.sunnahFirst + ' – ' + b.sunnahLast + '</span></button>';
    });
    h += '</div><p class="dar-source-line">المصدر: مجموعة fawazahmed0/hadith-api (بيانات sunnah.com) — الأرقام المعروضة هي ترقيم sunnah.com.</p>';
    body.innerHTML = h;
    return;
  }
  const b = darHadithBook;
  let h = '<button class="dar-back" onclick="darBackToHadithBooks()">← كل الكتب</button>' +
    '<h4 class="dar-h4">' + darEsc(coll.collection) + ' — كتاب ' + darEsc(b.name) + '</h4>' +
    '<div id="darHadithList"><div class="dar-loading">جاري تحميل الأحاديث…</div></div>' +
    '<div class="dar-pager"><button class="dar-btn" id="darHadithPrev" onclick="darHadithPrevPage()">‹ السابق</button>' +
    '<span id="darHadithPageLabel"></span>' +
    '<button class="dar-btn dar-btn-primary" id="darHadithNext" onclick="darHadithNextPage()">التالي ›</button></div>';
  body.innerHTML = h;
  darLoadHadithPage();
}
function darFilterHadithBooks(q) {
  q = darNormSearch(q);
  document.querySelectorAll('#darBookGrid .dar-book-card').forEach(function (c) {
    c.style.display = (!q || darNormSearch(c.getAttribute('data-name')).indexOf(q) !== -1) ? '' : 'none';
  });
}
function darOpenHadithBook(n) {
  darHadithBook = DAR_HADITH[darHadithColl].books.find(function (b) { return b.n === n; });
  darHadithPage = 0;
  darRenderHadithBody();
}
function darBackToHadithBooks() { darHadithBook = null; darHadithPage = 0; darRenderHadithBody(); }
function darHadithPrevPage() { if (darHadithPage > 0) { darHadithPage--; darLoadHadithPage(); } }
function darHadithNextPage() { darHadithPage++; darLoadHadithPage(); }

async function darFetchHadith(coll, n) {
  const key = coll + '-' + n;
  if (DARQ.hadithCache[key]) return DARQ.hadithCache[key];
  const edition = DAR_HADITH[coll].edition;
  for (let attempt = 0; attempt < 2; attempt++) {
    try {
      const r = await fetch(DARQ.cdnHadith + '/' + edition + '/' + n + '.json');
      if (!r.ok) continue;
      const d = await r.json();
      // per-hadith file shape: { metadata, hadiths: [ { hadithnumber, text, ... } ] }
      const h = (d && Array.isArray(d.hadiths) && d.hadiths.length) ? d.hadiths[0] : d;
      if (h && h.text) { DARQ.hadithCache[key] = h; return h; }
      return h; // empty-text entry — return as-is so caller can skip it
    } catch (e) { /* retry once */ }
  }
  return null;
}
async function darLoadHadithPage() {
  const list = darEl('darHadithList');
  const label = darEl('darHadithPageLabel');
  const prev = darEl('darHadithPrev'), next = darEl('darHadithNext');
  if (!list || !darHadithBook) return;
  const b = darHadithBook;
  const start = b.first + darHadithPage * DAR_HADITH_PAGE;
  list.innerHTML = '<div class="dar-loading">جاري تحميل الأحاديث…</div>';
  const items = [];
  let n = start, tried = 0;
  while (items.length < DAR_HADITH_PAGE && n <= b.last && tried < DAR_HADITH_PAGE * 4) {
    const d = await darFetchHadith(darHadithColl, n);
    tried++;
    if (d && d.text && d.text.trim()) items.push(d);
    n++;
  }
  if (!items.length) {
    list.innerHTML = '<div class="dar-error">لا توجد أحاديث في هذه الصفحة — جرّب الصفحة السابقة.</div>';
  } else {
    list.innerHTML = items.map(function (d) { return darHadithCard(d, b); }).join('');
  }
  if (label) label.textContent = 'صفحة ' + (darHadithPage + 1);
  if (prev) prev.disabled = darHadithPage === 0;
  if (next) next.disabled = (start + DAR_HADITH_PAGE) > b.last;
}
function darHadithCard(d, book) {
  const coll = DAR_HADITH[darHadithColl];
  // Muslim hadiths without an arabicnumber are unassigned duplicates in the
  // dataset (e.g. Muslim 41 #5885-5886, 33 #4968-4971): their sunnah.com
  // number cannot be verified, so show the dataset number and NO sunnah link.
  const hasSunnahNum = !(darHadithColl === 'muslim' && !d.arabicnumber);
  const num = (darHadithColl === 'muslim' && d.arabicnumber)
    ? Math.floor(Number(d.arabicnumber)) : d.hadithnumber;
  const grade = (d.grades && d.grades.length) ? d.grades[0].grade : null;
  const gradeLine = grade ? darEsc(grade) : 'صحيح — ' + darEsc(coll.collection) + ' (صحة المجموعة)';
  const numLine = hasSunnahNum ? ('حديث رقم ' + num) : ('حديث رقم ' + num + ' (ترقيم مجموعة البيانات)');
  const sunnahUrl = 'https://sunnah.com/' + darHadithColl + '/' + num;
  return '<div class="dar-hadith-card"><div class="dar-hadith-text">' + darEsc(d.text) + '</div>' +
    '<div class="dar-hadith-meta">' + darEsc(coll.collection) + ' — كتاب ' + darEsc(book.name) +
    ' • ' + numLine + ' • ' + gradeLine + '</div>' +
    (hasSunnahNum ? '<div class="dar-hadith-links"><a href="' + sunnahUrl + '" target="_blank" rel="noopener">اقرأ الحديث على sunnah.com ↗</a></div>' : '') + '</div>';
}


/* ---------- درس اليوم (kuttab method: سَبَق / سَبْقي / مَنْزِل) ---------- */
const DAR_MEM_KEY = 'darquran_mem';
const DAR_LESSON_KEY = 'darquran_lesson';
const DAR_MEM_INTERVALS = [1, 3, 7, 14, 30]; // days per level 1..5

function darTodayStr() {
  const d = new Date();
  return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
}
function darAddDays(dateStr, days) {
  const d = new Date(dateStr + 'T12:00:00');
  d.setDate(d.getDate() + days);
  return d.getFullYear() + '-' + String(d.getMonth() + 1).padStart(2, '0') + '-' + String(d.getDate()).padStart(2, '0');
}
function darGetMem() {
  try { return JSON.parse(localStorage.getItem(DAR_MEM_KEY) || '{}'); } catch (e) { return {}; }
}
function darSetMem(m) { try { localStorage.setItem(DAR_MEM_KEY, JSON.stringify(m)); } catch (e) {} }
function darGetLesson() {
  try {
    const l = JSON.parse(localStorage.getItem(DAR_LESSON_KEY) || 'null');
    if (l && l.current) {
      // the lesson path lives INSIDE Juz Amma (surahs 78-114) only; repair
      // any stored state that escaped the juz (old bug walked down to 1).
      if (l.current < 78 || l.current > 114) {
        l.current = 114;
        // persist the repair so a stale stored value cannot resurface
        try { localStorage.setItem(DAR_LESSON_KEY, JSON.stringify(l)); } catch (e) {}
      }
      return l;
    }
  } catch (e) {}
  return { current: 114, done: [] };
}
function darSetLesson(l) { try { localStorage.setItem(DAR_LESSON_KEY, JSON.stringify(l)); } catch (e) {} }
function darMemStateLabel(surah, ayah) {
  const m = darGetMem()[surah + ':' + ayah];
  if (!m) return '';
  if (m.level >= 5) return '✓ محفوظة — مراجعة بعد شهر';
  return '✓ محفوظة — المراجعة القادمة: ' + m.due;
}
function darMarkMemorised(surah, ayah, btn) {
  const mem = darGetMem();
  const key = surah + ':' + ayah;
  const cur = mem[key] || { level: 0, due: darTodayStr() };
  const level = Math.min(cur.level + 1, 5);
  const due = darAddDays(darTodayStr(), DAR_MEM_INTERVALS[level - 1]);
  mem[key] = { level: level, due: due };
  darSetMem(mem);
  const lbl = document.getElementById('mem-' + surah + '-' + ayah);
  if (lbl) lbl.textContent = darMemStateLabel(surah, ayah);
  if (btn) { btn.textContent = '✓ تم — حاولت كويس'; btn.disabled = true; }
  darRenderLessonProgress();
}
function darDueToday() {
  const mem = darGetMem(), today = darTodayStr(), out = [];
  Object.keys(mem).forEach(function (k) {
    if (mem[k].due <= today) {
      const parts = k.split(':');
      out.push({ surah: Number(parts[0]), ayah: Number(parts[1]), level: mem[k].level });
    }
  });
  return out.sort(function (a, b) { return a.surah - b.surah || a.ayah - b.ayah; });
}
function darRenderLessonProgress() {
  const el = darEl('darLessonProgress');
  if (!el) return;
  const l = darGetLesson();
  const due = darDueToday();
  const cur = DAR_SURAHS[l.current - 1];
  el.innerHTML = 'السورة الحالية: <b>' + darEsc(cur.name) + '</b> • سور مكتملة: ' + l.done.length +
    ' • آيات مستحقة للمراجعة اليوم: <b>' + due.length + '</b>';
}

let darLessonStep = 1;
/* Quiz gate: the lesson counts as done ONLY after the quiz is answered.
   Reset on every new lesson (darRenderLessonView) and on finish. */
let darQuizDone = {};
/* switch top-level tab (uses the app's generic tab switcher) */
function darSwitchTab(tab) {
  const b = document.querySelector('[data-tab="' + tab + '"]');
  if (b) { b.click(); return; }
  // sections that live inside «تعلّم» have no top tab of their own
  // (e.g. «manners» — the legacy shim darShowSub('manners') still calls here)
  if (typeof darOpenLearnSection === 'function' && ['quran', 'lesson', 'journey', 'tajweed', 'hadith', 'exercises', 'manners'].indexOf(tab) !== -1) darOpenLearnSection(tab);
}
/* render the lesson into its own tab if it is still empty (lazy, no step reset) */
function darEnsureLesson() {
  const host = darEl('lessonContent');
  if (host && !host.innerHTML.trim() && !host.dataset.loading) darRenderLessonView(host);
}
function darOpenLesson() {
  darLessonStep = 1;
  const host = darEl('lessonContent');
  if (host) darRenderLessonView(host);
  darSwitchTab('lesson');
  window.scrollTo(0, 0);
}
function darLessonStepName(i) {
  return ['', 'اسمع', 'ردّد', 'احفظ', 'افهم', 'طبّق التجويد', 'اختبر نفسك'][i];
}
async function darRenderLessonView(host) {
  const l = darGetLesson();
  darQuizDone = {};
  const n = l.current;
  const meta = DAR_SURAHS[n - 1];
  const chapter = DAR_MATN.chapters[l.done.length % DAR_MATN.chapters.length];
  host.innerHTML = '<div class="dar-loading">جاري تجهيز درس اليوم…</div>';
  host.dataset.loading = '1';
  let d;
  try { d = await darFetchSurah(n); }
  catch (e) {
    delete host.dataset.loading;
    host.innerHTML = '<div class="dar-error">تعذّر تحميل درس اليوم — تحقق من الإنترنت.</div><button class="dar-btn" onclick="darBackToSurahs()">رجوع</button>';
    return;
  }
  const doneCount = l.done.length;
  let h = '<button class="dar-back" onclick="darBackToSurahs()">← كل السور</button>';
  h += '<div class="dar-lesson-head"><h3 class="dar-lesson-title">📖 درس اليوم</h3>' +
    '<div class="dar-lesson-surah">' + darEsc(d.name) + ' — ' + d.ayahs.length + ' آية • ' + meta.type + '</div>' +
    '<div class="dar-lesson-sub">المسار: جزء عمّ — سورة ' + (114 - n + 1) + ' من 37 • حوالي 15 دقيقة</div></div>';
  h += darNoTtsLine();
  h += '<div class="dar-steps">' + [1, 2, 3, 4, 5, 6].map(function (i) {
    return '<button class="dar-step' + (darLessonStep === i ? ' active' : '') + '" onclick="darGoStep(' + i + ')">' + i + ' — ' + darLessonStepName(i) + '</button>';
  }).join('') + '</div>';
  h += '<div id="darLessonStep"></div>';
  h += '<div class="dar-lesson-nav"><button class="dar-btn" id="darPrevStep" onclick="darGoStep(' + (darLessonStep - 1) + ')">‹ الخطوة السابقة</button>' +
    '<button class="dar-btn dar-btn-primary" id="darNextStep" onclick="darGoStep(' + (darLessonStep + 1) + ')">الخطوة التالية ›</button></div>';
  host.innerHTML = h;
  delete host.dataset.loading;
  darRenderLessonStep(d, chapter);
}
function darGoStep(i) {
  if (i < 1) i = 1;
  if (i > 6) i = 6;
  darLessonStep = i;
  const l = darGetLesson();
  const chapter = DAR_MATN.chapters[l.done.length % DAR_MATN.chapters.length];
  const d = DARQ.surahCache[darSurahCacheKey(l.current)];
  if (!d) { darOpenLesson(); return; }
  // re-render step buttons active state
  document.querySelectorAll('.dar-step').forEach(function (b, idx) {
    b.classList.toggle('active', idx + 1 === i);
  });
  const prev = darEl('darPrevStep'), next = darEl('darNextStep');
  if (prev) { prev.setAttribute('onclick', 'darGoStep(' + (i - 1) + ')'); prev.style.visibility = i === 1 ? 'hidden' : ''; }
  if (next) { next.setAttribute('onclick', 'darGoStep(' + (i + 1) + ')'); next.style.visibility = i === 6 ? 'hidden' : ''; }
  darRenderLessonStep(d, chapter);
  window.scrollTo(0, 0);
}
function darRenderLessonStep(d, chapter) {
  const host = darEl('darLessonStep');
  if (!host) return;
  const l = darGetLesson();
  const n = d.n;
  let h = '';
  if (darLessonStep === 1) {
    h += '<div class="dar-step-intro"><h4 class="dar-h4">١ — اسمع 👂</h4><p>استمع لتلاوة الشيخ آية آية، ثم استمع مرة أخرى وأنت تنظر في المصحف.</p></div>';
    const kid = DAR_VIDEOS.kids[String(n)];
    if (kid) h += '<div class="dar-kids-card"><div class="dar-kids-title">🧒 تلقين الأطفال — تكرار للتحفيظ</div>' + darVideoCard(kid) + '</div>';
    h += '<div class="dar-ayahs">' + d.ayahs.map(function (a) { return darAyahCard(a, n, {}); }).join('') + '</div>';
  } else if (darLessonStep === 2) {
    h += '<div class="dar-step-intro"><h4 class="dar-h4">٢ — ردّد 🗣️</h4><p>ردّد كل آية بعد الشيخ ثلاث مرات. اضغط «استمع» ثم ردّد بصوتك — لا بأس إن أخطأت، جرّب مرة أخرى.</p></div>';
    h += '<div class="dar-ayahs">' + d.ayahs.map(function (a) { return darAyahCard(a, n, {}); }).join('') + '</div>';
  } else if (darLessonStep === 3) {
    const mem = darGetMem();
    const prevSurah = n < 114 ? n + 1 : null; // yesterday's lesson = next surah number in descending path
    const due = darDueToday().filter(function (x) { return x.surah !== n; });
    h += '<div class="dar-step-intro"><h4 class="dar-h4">٣ — احفظ 📖</h4><p>احفظ مقداراً صغيراً فقط — آية أو آيتين — ثم راجع ما سبق. التكرار المتباعد هو سرّ التثبيت.</p></div>';
    h += '<div class="dar-mem-block"><div class="dar-mem-title">سَبَق — جديد اليوم (' + d.ayahs.length + ' آية)</div>' +
      '<div class="dar-ayahs">' + d.ayahs.map(function (a) { return darAyahCard(a, n, { mem: true }); }).join('') + '</div></div>';
    if (prevSurah) {
      const prevMeta = DAR_SURAHS[prevSurah - 1];
      h += '<div class="dar-mem-block"><div class="dar-mem-title">سَبْقي — درس الأمس: سورة ' + darEsc(darSurahBare(prevMeta.name)) + '</div>' +
        '<button class="dar-btn" onclick="darOpenSurah(' + prevSurah + ')">راجع سورة ' + darEsc(darSurahBare(prevMeta.name)) + '</button></div>';
    }
    h += '<div class="dar-mem-block"><div class="dar-mem-title">مَنْزِل — مراجعة اليوم (' + due.length + ' آية مستحقة)</div>';
    if (!due.length) h += '<p class="dar-mem-empty">لا آيات مستحقة للمراجعة اليوم — أحسنت، أنت منتظم! 👏</p>';
    else {
      const bySurah = {};
      due.forEach(function (x) { (bySurah[x.surah] = bySurah[x.surah] || []).push(x.ayah); });
      h += Object.keys(bySurah).map(function (s) {
        return '<div class="dar-mem-due">سورة ' + darEsc(darSurahBare(DAR_SURAHS[s - 1].name)) + ' — الآيات: ' + bySurah[s].join('، ') +
          ' <button class="dar-btn dar-btn-small" onclick="darOpenSurah(' + s + ')">راجعها</button></div>';
      }).join('');
    }
    h += '</div>';
  } else if (darLessonStep === 4) {
    h += '<div class="dar-step-intro"><h4 class="dar-h4">٤ — افهم 💡</h4><p>المعنى المختصر لكل آية من «التفسير الميسر» — اضغط على كل آية لقراءة معناها.</p></div>';
    h += '<div class="dar-ayahs">' + d.ayahs.map(function (a) { return darAyahCard(a, n, { tafsir: true }); }).join('') + '</div>';
    h += '<p class="dar-source-line">التفسير: التفسير الميسر — مجمع الملك فهد لطباعة المصحف الشريف.</p>';
  } else if (darLessonStep === 5) {
    h += '<div class="dar-step-intro"><h4 class="dar-h4">٥ — طبّق التجويد 🎯</h4><p>حكم اليوم من متن تحفة الأطفال — شاهد شرح الشيخ، ثم ابحث عن الحكم في آيات الدرس.</p></div>';
    h += '<div class="dar-chapter"><h4 class="dar-chapter-title">' + darEsc(chapter.title) + '</h4>' +
      '<p class="dar-chapter-intro">' + darEsc(chapter.intro) + '</p>' +
      darMatnVerses(chapter.verses) + darMatnCite() +
      chapter.rules.map(darRuleCard).join('') + '</div>';
    if (chapter.video) h += darVideoCard(chapter.video);
    h += '<div class="dar-spot"><div class="dar-spot-title">🔍 ابحث عن الحكم في آيات الدرس</div>' +
      '<p>في آيات سورة ' + darEsc(darSurahBare(d.name)) + '، ابحث عن موضعٍ يظهر فيه حكم «' + darEsc(chapter.rules[0].name) + '» — مثالك في الأعلى يرشدك.</p></div>';
  } else if (darLessonStep === 6) {
    const qs = DAR_QUIZ[chapter.id] || [];
    h += '<div class="dar-step-intro"><h4 class="dar-h4">٦ — اختبر نفسك ✅</h4><p>أخفِ الآيات وجرّب أن تسمعها من حفظك — لا بأس إن نسيت، هذا هو التعلّم.</p></div>';
    h += '<div class="dar-ayahs">' + d.ayahs.map(function (a) { return darAyahCard(a, n, { hide: true }); }).join('') + '</div>';
    h += '<div class="dar-quiz"><div class="dar-quiz-title">سؤالان عن حكم اليوم: ' + darEsc(chapter.title) + '</div>';
    qs.forEach(function (q, qi) {
      h += '<div class="dar-q" id="dar-q-' + qi + '"><div class="dar-q-text">' + darEsc(q.q) + '</div>' +
        q.options.map(function (o, oi) {
          return '<button class="dar-q-opt" onclick="darAnswerQuiz(' + qi + ',' + oi + ',' + q.a + ',this)">' + darEsc(o) + '</button>';
        }).join('') + '<div class="dar-q-feedback"></div></div>';
    });
    h += '</div>';
    h += '<div class="dar-correction"><div class="dar-correction-title">🎧 صحّح تلاوتك مع الشيخ</div>' +
      '<p>شاهد تصحيح التلاوة آية آية مع تطبيق أحكام التجويد (رواية حفص):</p>' +
      darVideoCard(DAR_VIDEOS.correction_nuh) + '</div>';
    h += '<div class="dar-finish"><button id="darFinishBtn" class="dar-btn dar-btn-primary dar-btn-big" onclick="darFinishLesson()">أنهيت درس اليوم ✓</button>' +
      '<div class="dar-finish-hint" id="darFinishHint">أجب عن سؤالي الاختبار أولاً — الاختبار جزء من الدرس، وبعده تُحسب السورة مكتملة.</div>' +
      '<div class="dar-encourage">حاولت كويس — كل آية تحفظها خطوة، وكل مراجعة تثبّت ما سبق. 🌿</div></div>';
  }
  host.innerHTML = h;
  darUpdateFinishBtn();
}
function darAnswerQuiz(qi, oi, correct, btn) {
  const q = btn.closest('.dar-q');
  const fb = q.querySelector('.dar-q-feedback');
  if (oi === correct) {
    darQuizDone[qi] = true; // الإجابة الصحيحة وحدها تُحتسَب — الغلط لا يُنهي السؤال
    q.querySelectorAll('.dar-q-opt').forEach(function (b) { b.disabled = true; });
    btn.classList.add('correct');
    fb.innerHTML = '<span class="dar-fb-good">أحسنت — إجابة صحيحة! حاولت كويس 👏</span>';
  } else {
    btn.classList.add('wrong');
    fb.innerHTML = '<span class="dar-fb-soft">لسه — حاول مرة تانية، وافتكر شرح الدرس.</span>';
    setTimeout(function () { btn.classList.remove('wrong'); }, 1200);
  }
  darUpdateFinishBtn();
}
function darQuizTotal() {
  const l = darGetLesson();
  const ch = DAR_MATN.chapters[l.done.length % DAR_MATN.chapters.length];
  return (DAR_QUIZ[ch.id] || []).length;
}
function darUpdateFinishBtn() {
  const btn = document.getElementById('darFinishBtn');
  if (!btn) return;
  const ok = Object.keys(darQuizDone).length >= darQuizTotal();
  btn.disabled = !ok;
  const hint = document.getElementById('darFinishHint');
  if (hint) hint.style.display = ok ? 'none' : '';
}
function darFinishLesson() {
  const l = darGetLesson();
  const ch = DAR_MATN.chapters[l.done.length % DAR_MATN.chapters.length];
  const qs = DAR_QUIZ[ch.id] || [];
  if (Object.keys(darQuizDone).length < qs.length) {
    alert('أجب عن سؤالي الاختبار أولاً — الاختبار جزء من الدرس، وبعده تُحسب السورة مكتملة. 🌿');
    darGoStep(6);
    return;
  }
  if (l.done.indexOf(l.current) === -1) l.done.push(l.current);
  // Juz Amma path: 114 -> ... -> 78, then wrap back to 114. Never below 78.
  l.current = (l.current <= 78) ? 114 : l.current - 1;
  darSetLesson(l);
  darQuizDone = {};
  // the daily streak advances ONLY by completing a Quran lesson
  if (typeof touchStreak === 'function') touchStreak();
  darLessonStep = 1;
  const next = DAR_SURAHS[l.current - 1];
  alert('بارك الله فيك! 🌿\nأنهيت درس اليوم — حاولت كويس.\nالدرس القادم: سورة ' + darSurahBare(next.name) + '.');
  darOpenLesson();
}

/* ============================================================
   NEW in v2.0.0 (steers 8-12) — appended 2026-11-23
   - Reciters (3 verified human reciters) + mushaf display helpers
   - Home (two doors + namesake hadith from data/manners.json)
   - Manners game («تعمل إيه لو…؟» — original situations, verified evidence)
   - Interactive exercises (all generated from the verified Uthmani text)
   ============================================================ */

/* ---------- reciters: recorded human reciters only ---------- */
// Verified 2026-11-23 (AlQuran Cloud, HTTP 200 for surah 114 + MP3 200):
// ar.alafasy, ar.husary, ar.minshawi.
// NOTE: ar.husaryteacher is NOT a valid audio edition — the API returns a text
// edition (quran-uthmani-quran-academy) with no audio, so الحصري uses ar.husary.
const DAR_RECITERS = [
  { id: 'ar.alafasy', name: 'مشاري راشد العفاسي' },
  { id: 'ar.husary', name: 'محمود خليل الحصري' },
  { id: 'ar.minshawi', name: 'محمد صديق المنشاوي' },
];
const DAR_RECITER_KEY = 'darquran_reciter';
function darReciter() {
  try {
    const r = localStorage.getItem(DAR_RECITER_KEY);
    if (DAR_RECITERS.some(function (x) { return x.id === r; })) return r;
  } catch (e) {}
  return 'ar.alafasy';
}
function darReciterName() {
  const r = DAR_RECITERS.find(function (x) { return x.id === darReciter(); });
  return r ? r.name : 'مشاري راشد العفاسي';
}
function darSetReciter(id) {
  try { localStorage.setItem(DAR_RECITER_KEY, id); } catch (e) {}
  if (DARQ.surahCache[darSurahCacheKey(darCurrentSurah)]) delete DARQ.surahCache[darSurahCacheKey(darCurrentSurah)];
  darRenderQuran();
}
function darReciterPicker() {
  return '<div class="dar-reciter-row"><span class="dar-reciter-label">🎙️ القارئ:</span>' +
    DAR_RECITERS.map(function (r) {
      return '<button class="dar-reciter-btn' + (darReciter() === r.id ? ' active' : '') +
        '" onclick="darSetReciter(\'' + r.id + '\')">' + darEsc(r.name) + '</button>';
    }).join('') + '</div>';
}
function darSurahCacheKey(n) { return n + ':' + darReciter(); }
function darArNum(n) { return String(n).replace(/[0-9]/g, function (d) { return '٠١٢٣٤٥٦٧٨٩'[Number(d)]; }); }

/* The API prepends the Basmala to ayah 1 of surahs 2-114 (except 9). The mushaf lays
   the Basmala out as its own line, so we split it off for display — the header
   Basmala + the displayed ayah 1 together equal the API's ayah 1 text, verbatim.
   The Basmala string itself comes from the API (surah 1, ayah 1), never typed. */
function darDisplayAyahs(d) {
  const n = d.n;
  if (n === 1 || n === 9 || !DARQ.basmala) return { basmala: '', ayahs: d.ayahs };
  const a0 = d.ayahs[0];
  if (!a0 || a0.text.indexOf(DARQ.basmala) !== 0) return { basmala: '', ayahs: d.ayahs };
  const rest = a0.text.slice(DARQ.basmala.length).replace(/^[\s\u200f]+/, '');
  const ayahs = d.ayahs.map(function (a, i) {
    if (i === 0) return { n: a.n, text: rest, audio: a.audio, tafsir: a.tafsir };
    return a;
  });
  return { basmala: DARQ.basmala, ayahs: ayahs };
}

/* ---------- HOME (two doors + namesake) ---------- */
async function darEnsureHome() {
  const el = darEl('homeNamesake');
  if (!el || el.dataset.done) return;
  try {
    const m = await darFetchManners();
    el.innerHTML = '<div class="dar-namesake-title">قال رسول الله ﷺ:</div>' +
      '<div class="dar-namesake-text">«' + darEsc(m.namesake.text) + '»</div>' +
      '<div class="dar-namesake-ref">' + darEsc(m.namesake.ref) + '</div>' +
      '<div class="dar-namesake-why">لهذا سمّينا التطبيق «علم ينتفع به» — علمٌ يبقى أجره بعد صاحبه.</div>';
    el.dataset.done = '1';
  } catch (e) { /* the doors still work without the namesake line */ }
}

/* ---------- MANNERS («تعمل إيه لو…؟» game) ---------- */
let DAR_MANNERS = null;
async function darFetchManners() {
  if (DAR_MANNERS) return DAR_MANNERS;
  const r = await fetch('data/manners.json');
  if (!r.ok) throw new Error('تعذّر تحميل السلوكيات');
  DAR_MANNERS = await r.json();
  return DAR_MANNERS;
}
const DAR_MANNERS_DONE_KEY = 'darquran_manners_done';
function darMannersDone() {
  try { return JSON.parse(localStorage.getItem(DAR_MANNERS_DONE_KEY) || '[]'); } catch (e) { return []; }
}
function darMannersMarkDone(id) {
  const d = darMannersDone();
  if (d.indexOf(id) === -1) {
    d.push(id);
    try { localStorage.setItem(DAR_MANNERS_DONE_KEY, JSON.stringify(d)); } catch (e) {}
  }
}
let darMannersView = 'groups'; // groups | group | game
let darMannersGroup = null, darMannersSit = null;
async function darEnsureManners() {
  const host = darEl('mannersContent');
  if (host && !host.innerHTML.trim()) await darRenderManners();
}
function darEvidenceCard(ev, label) {
  const kind = ev.kind === 'ayah' ? '📖 آية قرآنية' : '📜 حديث شريف';
  return '<div class="dar-evidence"><div class="dar-evidence-kind">' + kind + (label ? ' — ' + darEsc(label) : '') + '</div>' +
    '<div class="dar-evidence-text">' + darEsc(ev.text) + '</div>' +
    '<div class="dar-evidence-ref">' + darEsc(ev.ref) + '</div>' +
    '<div class="dar-evidence-src">المصدر: ' + darEsc(ev.source) + '</div></div>';
}
async function darRenderManners() {
  const host = darEl('mannersContent');
  if (!host) return;
  host.innerHTML = '<div class="dar-loading">جاري تحميل قسم السلوكيات…</div>';
  let m;
  try { m = await darFetchManners(); }
  catch (e) {
    host.innerHTML = '<div class="dar-error">تعذّر تحميل السلوكيات — تحقق من الإنترنت وحاول مجدداً.</div>';
    return;
  }
  const done = darMannersDone();
  let h = '';
  if (darMannersView === 'groups') {
    h += '<div class="dar-section-intro"><h3 class="dar-h3">🌿 قسم السلوكيات</h3>' +
      '<p>الأخلاق الحلوة هي الردّ على الأخلاق الوحشة اللي بتنتشر حوالينا. كل موقف في حياتك له اختيار صح — جرّبه بنفسك، ولو غلطت حاول تاني من غير عقاب.</p></div>';
    h += darEvidenceCard(m.namesake, 'لماذا «علم ينتفع به»؟');
    h += '<div class="dar-groups">';
    Object.keys(m.groups).forEach(function (g) {
      const gr = m.groups[g];
      const items = m.situations.filter(function (s) { return s.group === g; });
      const doneCount = items.filter(function (s) { return done.indexOf(s.id) !== -1; }).length;
      const badge = doneCount === items.length && items.length
        ? '<div class="dar-badge-won">🏅 وسام الأخلاق الحلوة — ' + darEsc(gr.name) + '</div>' : '';
      h += '<button class="dar-group-card" onclick="darOpenMannersGroup(\'' + g + '\')">' +
        '<span class="dar-group-icon">' + gr.icon + '</span>' +
        '<span class="dar-group-name">' + darEsc(gr.name) + '</span>' +
        '<span class="dar-group-desc">' + darEsc(gr.desc) + '</span>' +
        '<span class="dar-group-progress">' + doneCount + ' / ' + items.length + ' موقف</span>' + badge + '</button>';
    });
    h += '</div>';
    h += '<p class="dar-source-line">' + darEsc(m.sources_note) + '</p>';
  } else if (darMannersView === 'group') {
    const gr = m.groups[darMannersGroup];
    const items = m.situations.filter(function (s) { return s.group === darMannersGroup; });
    const doneCount = items.filter(function (s) { return done.indexOf(s.id) !== -1; }).length;
    h += '<button class="dar-back" onclick="darMannersBackGroups()">← كل المجموعات</button>';
    h += '<div class="dar-section-intro"><h3 class="dar-h3">' + gr.icon + ' ' + darEsc(gr.name) + '</h3>' +
      '<p>' + darEsc(gr.desc) + ' — خلصت ' + doneCount + ' من ' + items.length + ' موقف.</p></div>';
    if (doneCount === items.length && items.length) {
      h += '<div class="dar-badge-banner">🏅 <b>وسام الأخلاق الحلوة — ' + darEsc(gr.name) + '</b><br>أحسنت! خلصت كل مواقف هذه المجموعة. 👏</div>';
    }
    h += '<div class="dar-sit-list">';
    items.forEach(function (s) {
      const isDone = done.indexOf(s.id) !== -1;
      h += '<button class="dar-sit-card' + (isDone ? ' done' : '') + '" onclick="darOpenMannersGame(\'' + s.id + '\')">' +
        '<span class="dar-sit-check">' + (isDone ? '✓' : '○') + '</span>' +
        '<span class="dar-sit-title">' + darEsc(s.title) + '</span>' +
        '<span class="dar-sit-instead">' + darEsc(s.instead) + ' ← ' + darEsc(s.do) + '</span></button>';
    });
    h += '</div>';
  } else if (darMannersView === 'game') {
    const s = m.situations.find(function (x) { return x.id === darMannersSit; });
    if (!s) { darMannersView = 'groups'; darRenderManners(); return; }
    const gr = m.groups[s.group];
    h += '<button class="dar-back" onclick="darOpenMannersGroup(\'' + s.group + '\')">← مواقف ' + darEsc(gr.name) + '</button>';
    h += '<div class="dar-game" id="darGame">' +
      '<div class="dar-game-instead">' + darEsc(s.instead) + ' ← <b>' + darEsc(s.do) + '</b></div>' +
      '<h3 class="dar-h3">' + darEsc(s.title) + '</h3>' +
      '<div class="dar-game-sit">🤔 <b>تعمل إيه لو…؟</b><br>' + darEsc(s.situation) + '</div>' +
      '<div class="dar-game-choices">' +
      s.choices.map(function (c, i) {
        return '<button class="dar-choice" onclick="darAnswerManners(' + i + ',this)">' + darEsc(c.t) + '</button>';
      }).join('') + '</div>' +
      '<div class="dar-game-feedback" id="darGameFeedback"></div></div>';
  }
  host.innerHTML = h;
  window.scrollTo(0, 0);
}
function darMannersBackGroups() { darMannersView = 'groups'; darMannersGroup = null; darRenderManners(); }
function darOpenMannersGroup(g) { darMannersView = 'group'; darMannersGroup = g; darRenderManners(); }
function darOpenMannersGame(id) { darMannersView = 'game'; darMannersSit = id; darRenderManners(); }
function darAnswerManners(idx, btn) {
  const m = DAR_MANNERS;
  const s = m.situations.find(function (x) { return x.id === darMannersSit; });
  if (!s) return;
  const fb = document.getElementById('darGameFeedback');
  const choice = s.choices[idx];
  if (!choice.ok) {
    btn.classList.add('wrong');
    btn.disabled = true;
    if (fb) fb.innerHTML = '<div class="dar-fb-soft">حاول تاني 🙂 — فكّر: إيه التصرف الأحسن؟ لا يوجد عقاب ولا نقص نقاط.</div>';
    return;
  }
  btn.classList.add('correct');
  document.querySelectorAll('#darGame .dar-choice').forEach(function (b) { b.disabled = true; });
  let h = '<div class="dar-fb-good">👏 أحسنت — إجابة صحيحة! حاولت كويس.</div>';
  h += darEvidenceCard(s.evidence);
  if (s.evidence2) h += darEvidenceCard(s.evidence2);
  h += '<div class="dar-why"><b>ليه؟</b> ' + darEsc(s.why) + '</div>';
  h += '<div class="dar-action"><b>🌱 عمل اليوم:</b> ' + darEsc(s.action) + '</div>';
  h += '<button class="dar-btn dar-btn-primary dar-btn-big" onclick="darMannersFinish(\'' + s.id + '\')">✓ خلصتها — للموعـد القادم</button>';
  if (fb) fb.innerHTML = h;
  const fbEl = document.getElementById('darGameFeedback');
  if (fbEl) window.scrollTo(0, fbEl.offsetTop - 80);
}
function darMannersFinish(id) {
  darMannersMarkDone(id);
  const m = DAR_MANNERS;
  const s = m.situations.find(function (x) { return x.id === id; });
  const items = m.situations.filter(function (x) { return x.group === s.group; });
  const done = darMannersDone();
  if (items.every(function (x) { return done.indexOf(x.id) !== -1; })) {
    alert('🏅 وسام الأخلاق الحلوة — ' + m.groups[s.group].name + '!\nأحسنت! خلصت كل مواقف هذه المجموعة.');
  }
  darOpenMannersGroup(s.group);
}

/* ---------- EXERCISES (generated from the verified Uthmani text) ---------- */
/* Accuracy rule: every correct answer is a real word/ayah from the fetched surah
   text, and every distractor is a real word/ayah from the same text. Nothing is
   typed or invented. window.__darEx exposes the last generated exercise so the
   builder's verify script can check it against the source. */
const DAR_EX_KINDS = [
  { id: 'complete', name: 'أكمل الآية', icon: '✏️' },
  { id: 'order', name: 'رتّب الآيات', icon: '🔢' },
  { id: 'recite', name: 'سمّع من غير ما تشوف', icon: '🙈' },
  { id: 'rule', name: 'استخرج الحكم', icon: '🎯' },
  { id: 'which', name: 'من أي سورة؟', icon: '❓' },
  { id: 'repeat', name: 'تلقين وتكرار', icon: '🔁' },
  { id: 'word', name: 'كلمة كلمة', icon: '👆' },
  { id: 'map', name: 'خريطة الحفظ', icon: '🗺️' },
  { id: 'similar', name: 'المتشابهات', icon: '🔍' },
  { id: 'hard', name: 'الكلمات الصعبة', icon: '💪' },
];
const DAR_EX_RULES = [
  { id: 'ikhfa', name: 'الإخفاء', letters: 'صذثكجشقسدطزفتضظ' },
  { id: 'idgham', name: 'الإدغام', letters: 'يرملون' },
  { id: 'iqlab', name: 'الإقلاب', letters: 'ب' },
  { id: 'izhar', name: 'الإظهار', letters: 'ءأإؤئهعحغخ' },
];
let darExSurah = 112, darExKind = 'complete', darExRule = 0;
let darExState = null;
const DAR_HARD_KEY = 'darquran_hard_words';
function darHardWords() {
  try { return JSON.parse(localStorage.getItem(DAR_HARD_KEY) || '[]'); } catch (e) { return []; }
}
function darAddHardWord(w) {
  const list = darHardWords();
  if (!list.some(function (x) { return x.word === w.word && x.ayah === w.ayah && x.surah === w.surah; })) {
    list.push({ word: w.word, surah: w.surah, ayah: w.ayah, ok: 0 });
    try { localStorage.setItem(DAR_HARD_KEY, JSON.stringify(list)); } catch (e) {}
  }
}
function darHardWordOk(w) {
  let list = darHardWords();
  list = list.map(function (x) {
    if (x.word === w.word && x.ayah === w.ayah && x.surah === w.surah) x.ok = (x.ok || 0) + 1;
    return x;
  }).filter(function (x) { return (x.ok || 0) < 2; });
  try { localStorage.setItem(DAR_HARD_KEY, JSON.stringify(list)); } catch (e) {}
}
function darShuffle(arr) {
  const a = arr.slice();
  for (let i = a.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    const t = a[i]; a[i] = a[j]; a[j] = t;
  }
  return a;
}
function darStripDia(s) {
  return (s || '').replace(/[\u064B-\u0652\u0670\u0640\u06D6-\u06ED\u08D3-\u08E2\u08F0-\u08F2\u200A\u2060]/g, '');
}
function darWords(text) {
  // NB: the Uthmani text has U+200A HAIR SPACE *inside* words (before a dagger
  // alef, e.g. «صِرَٰط») — JS \s matches it, so split(/\s+/) would break
  // words apart. Split only on ASCII whitespace.
  return (text || '').split(/[ \n\r\t]+/).filter(function (w) { return w && w !== '۞' && w !== '۝'; });
}
async function darEnsureExercises() {
  const host = darEl('exercisesContent');
  if (host && !host.innerHTML.trim()) await darRenderExercises();
}
function darExSurahOptions() {
  const opts = [];
  [1, 36, 67].forEach(function (n) {
    opts.push('<option value="' + n + '"' + (darExSurah === n ? ' selected' : '') + '>سورة ' + darEsc(DAR_SURAHS[n - 1].name.replace(/سُورَةُ /g, '')) + ' (' + DAR_SURAHS[n - 1].ayahs + ' آية)</option>');
  });
  for (let n = 78; n <= 114; n++) {
    opts.push('<option value="' + n + '"' + (darExSurah === n ? ' selected' : '') + '>سورة ' + darEsc(DAR_SURAHS[n - 1].name.replace(/سُورَةُ /g, '')) + ' (' + DAR_SURAHS[n - 1].ayahs + ' آية)</option>');
  }
  return opts.join('');
}
async function darRenderExercises() {
  const host = darEl('exercisesContent');
  if (!host) return;
  host.innerHTML = '<div class="dar-loading">جاري تجهيز التمارين…</div>';
  let d;
  try { d = await darFetchSurah(darExSurah); }
  catch (e) {
    host.innerHTML = '<div class="dar-error">تعذّر تحميل السورة — تحقق من الإنترنت وحاول مجدداً.</div>';
    return;
  }
  const disp = darDisplayAyahs(d);
  const ayahs = disp.ayahs;
  let h = '<div class="dar-section-intro"><h3 class="dar-h3">✏️ التمارين التفاعلية</h3>' +
    '<p>كل التمارين مولّدة من نص المصحف الموثّق نفسه — الإجابة الصحيحة دائماً كلمة أو آية حقيقية من السورة، والاختيارات الأخرى كلمات وآيات حقيقية أيضاً. لا يوجد شيء مخترع.</p>' +
    '<p>التمارين متاحة الآن على: الفاتحة والملك ويس وجزء عمّ كاملاً (40 سورة) — وباقي سور المصحف قريباً إن شاء الله.</p></div>';
  h += '<div class="dar-ex-picker"><label>السورة: <select id="darExSurahSel" onchange="darExChangeSurah(this.value)">' +
    darExSurahOptions() + '</select></label></div>';
  h += '<div class="dar-ex-kinds">' + DAR_EX_KINDS.map(function (k) {
    return '<button class="dar-ex-kind' + (darExKind === k.id ? ' active' : '') + '" onclick="darExChangeKind(\'' + k.id + '\')">' + k.icon + ' ' + darEsc(k.name) + '</button>';
  }).join('') + '</div>';
  h += '<div id="darExArea"></div>';
  host.innerHTML = h;
  darRenderExercise(d, ayahs);
}
function darExChangeSurah(n) { darExSurah = Number(n); darRenderExercises(); }
function darExChangeKind(k) { darExKind = k; darRenderExercises(); }
function darExNew() { darRenderExercises(); }
function darRenderExercise(d, ayahs) {
  const area = darEl('darExArea');
  if (!area) return;
  const kind = DAR_EX_KINDS.find(function (k) { return k.id === darExKind; });
  let h = '<div class="dar-ex-head"><h4 class="dar-h4">' + kind.icon + ' ' + darEsc(kind.name) + ' — سورة ' + darEsc(darSurahBare(d.name)) + '</h4></div>';
  window.__darEx = null;
  if (darExKind === 'complete') h += darExBuildComplete(d, ayahs);
  else if (darExKind === 'order') h += darExBuildOrder(d, ayahs);
  else if (darExKind === 'recite') h += darExBuildRecite(d, ayahs);
  else if (darExKind === 'rule') h += darExBuildRule(d, ayahs);
  else if (darExKind === 'which') h += darExBuildWhich(d, ayahs);
  else if (darExKind === 'repeat') h += darExBuildRepeat(d, ayahs);
  else if (darExKind === 'word') h += darExBuildWord(d, ayahs);
  else if (darExKind === 'map') h += darExBuildMap();
  else if (darExKind === 'similar') h += darExBuildSimilar(d, ayahs);
  else if (darExKind === 'hard') h += darExBuildHard(d, ayahs);
  h += '<div class="dar-ex-foot"><button class="dar-btn" onclick="darExNew()">🔄 تمرين جديد</button>' +
    '<button class="dar-btn" onclick="darOpenSurah(' + d.n + ')">📖 اقرأ السورة كاملة</button></div>';
  area.innerHTML = h;
}
/* --- 1. أكمل الآية --- */
function darExBuildComplete(d, ayahs) {
  const cands = ayahs.filter(function (a) { return darWords(a.text).length >= 3; });
  if (!cands.length) return '<p class="dar-hint">هذه السورة قصيرة جداً لهذا التمرين — جرّب سورة أخرى.</p>';
  const a = cands[Math.floor(Math.random() * cands.length)];
  const words = darWords(a.text);
  const wi = 1 + Math.floor(Math.random() * (words.length - 2));
  const word = words[wi];
  const pool = [];
  ayahs.forEach(function (x) {
    darWords(x.text).forEach(function (w) { if (w !== word && pool.indexOf(w) === -1) pool.push(w); });
  });
  const distractors = darShuffle(pool).slice(0, 2);
  while (distractors.length < 2) distractors.push(words[(wi + 1 + distractors.length) % words.length]);
  const choices = darShuffle([word].concat(distractors));
  darExState = { kind: 'complete', surah: d.n, ayah: a.n, word: word, choices: choices };
  window.__darEx = { kind: 'complete', surah: d.n, ayah: a.n, correct: word, source: a.text, choices: choices };
  const shown = words.map(function (w, i) { return i === wi ? '«_____»' : darEsc(w); }).join(' ');
  return '<p>أكمل الآية رقم ' + a.n + ' من سورة ' + darEsc(darSurahBare(d.name)) + ':</p>' +
    '<div class="dar-ex-ayah">' + shown + ' <span class="dar-ayah-end">۝ ' + darArNum(a.n) + '</span></div>' +
    '<div class="dar-ex-choices">' + choices.map(function (c) {
      return '<button class="dar-choice" onclick="darExAnswerComplete(this)">' + darEsc(c) + '</button>';
    }).join('') + '</div><div class="dar-game-feedback" id="darExFeedback"></div>';
}
function darExAnswerComplete(btn) {
  const fb = document.getElementById('darExFeedback');
  const st = darExState;
  if (!st || (st.kind !== 'complete' && st.kind !== 'hard')) return;
  if (btn.textContent.trim() === st.word) {
    btn.classList.add('correct');
    document.querySelectorAll('#darExArea .dar-choice').forEach(function (b) { b.disabled = true; });
    darHardWordOk({ word: st.word, surah: st.surah, ayah: st.ayah });
    if (fb) fb.innerHTML = '<div class="dar-fb-good">👏 أحسنت — إجابة صحيحة! حاولت كويس.</div>';
  } else {
    btn.classList.add('wrong');
    btn.disabled = true;
    darAddHardWord({ word: st.word, surah: st.surah, ayah: st.ayah });
    if (fb) fb.innerHTML = '<div class="dar-fb-soft">لا بأس — جرّب اختياراً آخر. الكلمة الصحيحة ستظهر هنا لاحقاً في «الكلمات الصعبة» حتى تثبت.</div>';
  }
}
/* --- 2. رتّب الآيات --- */
function darExBuildOrder(d, ayahs) {
  const n = Math.min(4, ayahs.length);
  if (n < 2) return '<p class="dar-hint">هذه السورة آية واحدة — جرّب سورة أطول.</p>';
  const start = ayahs.length > n ? Math.floor(Math.random() * (ayahs.length - n + 1)) : 0;
  const seq = ayahs.slice(start, start + n);
  const shuffled = darShuffle(seq);
  darExState = { kind: 'order', surah: d.n, seq: seq.map(function (a) { return a.n; }), next: 0 };
  window.__darEx = { kind: 'order', surah: d.n, seq: seq.map(function (a) { return a.n; }), source: seq.map(function (a) { return a.text; }) };
  return '<p>اضغط على الآيات بالترتيب الصحيح:</p>' +
    '<div class="dar-ex-order">' + shuffled.map(function (a) {
      return '<button class="dar-order-item" data-ayah="' + a.n + '" onclick="darExAnswerOrder(this)">' + darEsc(a.text) + '</button>';
    }).join('') + '</div><div class="dar-game-feedback" id="darExFeedback"></div>';
}
function darExAnswerOrder(btn) {
  const fb = document.getElementById('darExFeedback');
  const st = darExState;
  if (!st || st.kind !== 'order') return;
  const want = st.seq[st.next];
  if (Number(btn.getAttribute('data-ayah')) === want) {
    btn.classList.add('correct');
    btn.disabled = true;
    st.next++;
    if (st.next >= st.seq.length) {
      if (fb) fb.innerHTML = '<div class="dar-fb-good">👏 أحسنت — رتّبت الآيات صح! حاولت كويس.</div>';
    } else if (fb) fb.innerHTML = '<div class="dar-fb-soft">صح — كمّل الآية اللي بعدها.</div>';
  } else {
    btn.classList.add('wrong');
    setTimeout(function () { btn.classList.remove('wrong'); }, 700);
    if (fb) fb.innerHTML = '<div class="dar-fb-soft">مش دي اللي بعدها — حاول تاني، لا يوجد عقاب.</div>';
  }
}
/* --- 3. سمّع من غير ما تشوف --- */
function darExBuildRecite(d, ayahs) {
  const a = ayahs[Math.floor(Math.random() * ayahs.length)];
  const words = darWords(a.text);
  darExState = { kind: 'recite', surah: d.n, ayah: a.n, words: words, revealed: 0 };
  window.__darEx = { kind: 'recite', surah: d.n, ayah: a.n, correct: a.text, source: a.text };
  return '<p>الآية رقم ' + a.n + ' من سورة ' + darEsc(darSurahBare(d.name)) + ' — سمّعها من حفظك، ثم قارن بنفسك:</p>' +
    '<div class="dar-ex-ayah" id="darReciteText">' + words.map(function (w, i) {
      return '<span class="dar-recite-word" data-i="' + i + '">•</span>';
    }).join(' ') + '</div>' +
    '<div class="row"><button class="dar-btn" onclick="darExHint()">💡 تلميح (أظهر الكلمة التالية)</button>' +
    '<button class="dar-btn" onclick="darExReveal()">👁 أظهر الآية وقارن</button></div>' +
    '<div class="row"><button class="dar-btn" id="darRecBtn" onclick="darExRecord(this)">🎤 سجّل وسمّع نفسك</button></div>' +
    '<div id="darReciteRec"></div>' +
    (a.tafsir ? '<details class="dar-tafsir"><summary>📘 معنى الآية (التفسير الميسر) — للتأكد بعد التسميع</summary><p>' + darEsc(a.tafsir) + '</p></details>' : '') +
    '<div class="dar-game-feedback" id="darExFeedback"></div>';
}
function darExHint() {
  const st = darExState;
  if (!st || st.kind !== 'recite') return;
  if (st.revealed >= st.words.length) return;
  const spans = document.querySelectorAll('#darReciteText .dar-recite-word');
  const sp = spans[st.revealed];
  if (sp) { sp.textContent = st.words[st.revealed]; sp.classList.add('revealed'); }
  st.revealed++;
}
function darExReveal() {
  const st = darExState;
  if (!st || st.kind !== 'recite') return;
  document.querySelectorAll('#darReciteText .dar-recite-word').forEach(function (sp, i) {
    sp.textContent = st.words[i]; sp.classList.add('revealed');
  });
  st.revealed = st.words.length;
  const fb = document.getElementById('darExFeedback');
  if (fb) fb.innerHTML = '<div class="dar-fb-good">قارن ما سمّعته بالنص — إن أخطأت، لا بأس: كرّرها ثلاث مرات. 🌿</div>';
}
let darRecRecorder = null, darRecChunks = [];
async function darExRecord(btn) {
  const box = document.getElementById('darReciteRec');
  if (darRecRecorder && darRecRecorder.state === 'recording') {
    darRecRecorder.stop();
    btn.textContent = '🎤 سجّل وسمّع نفسك';
    return;
  }
  try {
    const stream = await navigator.mediaDevices.getUserMedia({ audio: true });
    darRecChunks = [];
    darRecRecorder = new MediaRecorder(stream);
    darRecRecorder.ondataavailable = function (e) { if (e.data && e.data.size) darRecChunks.push(e.data); };
    darRecRecorder.onstop = function () {
      stream.getTracks().forEach(function (t) { t.stop(); });
      const blob = new Blob(darRecChunks, { type: darRecRecorder.mimeType || 'audio/webm' });
      const url = URL.createObjectURL(blob);
      if (box) box.innerHTML = '<div class="dar-hint">🎧 اسمع تسجيلك وقارنه بالنص:</div><audio controls src="' + url + '"></audio>' +
        '<div class="dar-hint">التسجيل للمقارنة فقط — لا يوجد تقييم آلي للتسميع في هذه النسخة.</div>';
    };
    darRecRecorder.start();
    btn.textContent = '⏹ إيقاف التسجيل';
  } catch (e) {
    if (box) box.innerHTML = '<div class="dar-hint">🎤 الميكروفون غير متاح على هذا الجهاز أو لم تسمح بالوصول — يمكنك التسميع بدون تسجيل، وقارن بنفسك عند إظهار الآية.</div>';
  }
}
/* --- 4. استخرج الحكم (deterministic from the Uthmani text) --- */
/* The Uthmani text writes the marks several ways, so the detector first
   NORMALISES them (positions of spaces never change, so word indexes stay valid):
   - sukun: U+0652 and U+06E1 (small high dotless khah) are the same mark
   - tanwin: closed U+064B/C/D and open U+08F0/1/2 are the same mark
   - U+06E2 (small high meem): after a noon it is the iqlab mark («مِنۢ»);
     after a plain vowel (064E/064F/0650) it is the tanwin's second stroke
     («أَحَدُۢ» = damma + 06E2 = tanwin damm; «حِلٌّۢ بِ» = iqlab);
     after a tanwin mark it is an extra mark and is dropped.
   A noon with NO mark at all is also sakinah: in this fully-vocalised text
   a vowelled noon always carries its vowel, so a bare noon
   (e.g. «مِن شَرِّ», «یَكُن لَّهُ») is sakinah by definition.
   A fathatan is followed by a silent alef («كُفُوًا») — skipped when looking
   for the rule letter. Returns [{ayah, wordIdx, word, text}]. */
function darExNormMarks(s) {
  return s
    .replace(/\u064E\u06E2/g, '\u064B').replace(/\u064F\u06E2/g, '\u064C').replace(/\u0650\u06E2/g, '\u064D')
    .replace(/([\u064B\u064C\u064D])\u06E2/g, '$1')
    .replace(/[\u08F0]/g, '\u064B').replace(/[\u08F1]/g, '\u064C').replace(/[\u08F2]/g, '\u064D')
    .replace(/\u06E1/g, '\u0652');
}
function darExFindRuleWords(ayahs, letters) {
  const out = [];
  const isMark = function (ch) { return /[\u064B-\u0655\u0670\u0640\u06D6-\u06ED\u08D3-\u08E2\u200A\u2060]/.test(ch); };
  ayahs.forEach(function (a) {
    const words = darWords(a.text);
    const joined = darExNormMarks(words.join(' '));
    for (let i = 0; i < joined.length; i++) {
      const c = joined[i];
      let j = -1, isIqlab = false;
      if (c === 'ن') {
        const n1 = joined[i + 1];
        if (n1 === '\u0652' || n1 === '\u06E2') { j = i + 2; if (n1 === '\u06E2') isIqlab = true; }
        else if (n1 === undefined || n1 === ' ' || !isMark(n1)) { j = i + 1; } // bare noon = sakinah
        // else: vowelled / shadda / tanwin after the noon — not sakinah
      } else if (c === '\u064B' || c === '\u064C' || c === '\u064D') {
        j = i + 1;
        if (c === '\u064B' && joined[j] === '\u0627') j++; // silent alef after fathatan
      }
      if (j < 0) continue;
      // the rule letter: first letter after j, skipping spaces (and stray marks)
      let k = j;
      while (k < joined.length && (joined[k] === ' ' || isMark(joined[k]))) k++;
      const next = joined[k];
      if (!next || letters.indexOf(next) === -1) continue;
      if (isIqlab && next !== 'ب') continue;
      const wi = (joined.slice(0, i + 1).match(/ /g) || []).length;
      out.push({ ayah: a.n, wordIdx: wi, word: words[wi] || '', text: a.text });
    }
  });
  return out;
}
function darExBuildRule(d, ayahs) {
  let rule = DAR_EX_RULES[darExRule % DAR_EX_RULES.length];
  let hits = darExFindRuleWords(ayahs, rule.letters);
  let fallback = null;
  if (!hits.length) {
    // try the other rules in this surah before falling back to the matn example
    for (let k = 1; k < DAR_EX_RULES.length; k++) {
      const r2 = DAR_EX_RULES[(darExRule + k) % DAR_EX_RULES.length];
      const h2 = darExFindRuleWords(ayahs, r2.letters);
      if (h2.length) { darExRule = (darExRule + k) % DAR_EX_RULES.length; rule = DAR_EX_RULES[darExRule]; hits = h2; break; }
    }
  }
  if (!hits.length) {
    // fallback: the rule's verified example fragment from تحفة الأطفال
    // the matn names the rules «الإظهار الحلقي» / «الإخفاء الحقيقي» — match by prefix
    const ch = DAR_MATN.chapters.find(function (c) { return c.rules.some(function (r) { return r.name.indexOf(rule.name) === 0; }); });
    const rr = ch ? ch.rules.find(function (r) { return r.name.indexOf(rule.name) === 0; }) : null;
    if (!rr) return '<p class="dar-hint">لا يوجد موضع لهذا الحكم في هذه السورة — جرّب سورة أخرى.</p>';
    fallback = rr;
    const fragWords = darWords(rr.example.frag);
    // the correct word is computed from the fragment itself (deterministic):
    // the word holding the noon sakinah / tanween before a rule letter
    const fragHits = darExFindRuleWords([{ n: rr.example.ayah, text: rr.example.frag }], rule.letters);
    const correctWord = fragHits.length ? fragHits[0].word : fragWords[0];
    darExState = { kind: 'rule', surah: d.n, rule: rule.name, ayah: rr.example.ayah, word: correctWord, fallback: true };
    window.__darEx = { kind: 'rule', surah: d.n, rule: rule.name, correct: correctWord, source: rr.example.frag, fallback: true };
    return '<p>اضغط على الكلمة التي فيها حكم <b>' + darEsc(rule.name) + '</b> (من المثال الموثّق في المتن):</p>' +
      '<div class="dar-ex-ayah">' + fragWords.map(function (w) {
        return '<button class="dar-word-btn" onclick="darExAnswerRule(this)">' + darEsc(w) + '</button>';
      }).join(' ') + '</div>' +
      '<div class="dar-hint">المثال من القرآن الكريم — سورة ' + darEsc(darSurahBare(DAR_SURAHS[rr.example.surah - 1].name)) + '، آية ' + rr.example.ayah + ' — ' + darEsc(rr.example.note) + '</div>' +
      '<div class="dar-game-feedback" id="darExFeedback"></div>';
  }
  const hit = hits[Math.floor(Math.random() * hits.length)];
  const a = ayahs.find(function (x) { return x.n === hit.ayah; });
  const words = darWords(a.text);
  darExState = { kind: 'rule', surah: d.n, rule: rule.name, ayah: a.n, word: hit.word, wordIdx: hit.wordIdx };
  window.__darEx = { kind: 'rule', surah: d.n, rule: rule.name, correct: hit.word, source: a.text, ayah: a.n };
  return '<p>اضغط على الكلمة التي فيها حكم <b>' + darEsc(rule.name) + '</b> في الآية رقم ' + a.n + ':</p>' +
    '<div class="dar-ex-ayah">' + words.map(function (w, i) {
      return '<button class="dar-word-btn" data-i="' + i + '" onclick="darExAnswerRule(this)">' + darEsc(w) + '</button>';
    }).join(' ') + '</div>' +
    '<div class="row"><button class="dar-btn dar-btn-small" onclick="darExNextRule()">حكم آخر</button></div>' +
    '<div class="dar-game-feedback" id="darExFeedback"></div>';
}
function darExNextRule() { darExRule = (darExRule + 1) % DAR_EX_RULES.length; darRenderExercises(); }
function darExAnswerRule(btn) {
  const fb = document.getElementById('darExFeedback');
  const st = darExState;
  if (!st || st.kind !== 'rule') return;
  const ok = st.fallback
    ? btn.textContent.trim() === st.word
    : Number(btn.getAttribute('data-i')) === st.wordIdx;
  if (ok) {
    btn.classList.add('correct');
    document.querySelectorAll('#darExArea .dar-word-btn').forEach(function (b) { b.disabled = true; });
    if (fb) fb.innerHTML = '<div class="dar-fb-good">👏 أحسنت — وجدت الحكم! حكم «' + darEsc(st.rule) + '» في كلمة «' + darEsc(st.word) + '». حاولت كويس.</div>';
  } else {
    btn.classList.add('wrong');
    btn.disabled = true;
    if (fb) fb.innerHTML = '<div class="dar-fb-soft">مش دي — ابحث عن النون الساكنة أو التنوين وبعدها حرف الحكم. حاول تاني.</div>';
  }
}
/* --- 5. من أي سورة؟ --- */
function darExBuildWhich(d, ayahs) {
  const a = ayahs[Math.floor(Math.random() * ayahs.length)];
  const others = darShuffle(DAR_SURAHS.filter(function (s) { return s.n !== d.n; })).slice(0, 2);
  const choices = darShuffle([d].concat(others));
  darExState = { kind: 'which', surah: d.n, ayah: a.n };
  window.__darEx = { kind: 'which', surah: d.n, ayah: a.n, correct: d.name, source: a.text, choices: choices.map(function (s) { return s.name; }) };
  return '<p>هذه الآية من أي سورة؟</p>' +
    '<div class="dar-ex-ayah">' + darEsc(a.text) + ' <span class="dar-ayah-end">۝ ' + darArNum(a.n) + '</span></div>' +
    '<div class="dar-ex-choices">' + choices.map(function (s) {
      return '<button class="dar-choice" data-n="' + s.n + '" onclick="darExAnswerWhich(this)">' + darEsc(s.name) + '</button>';
    }).join('') + '</div><div class="dar-game-feedback" id="darExFeedback"></div>';
}
function darExAnswerWhich(btn) {
  const fb = document.getElementById('darExFeedback');
  const st = darExState;
  if (!st || st.kind !== 'which') return;
  if (Number(btn.getAttribute('data-n')) === st.surah) {
    btn.classList.add('correct');
    document.querySelectorAll('#darExArea .dar-choice').forEach(function (b) { b.disabled = true; });
    if (fb) fb.innerHTML = '<div class="dar-fb-good">👏 أحسنت — إجابة صحيحة!</div>';
  } else {
    btn.classList.add('wrong');
    btn.disabled = true;
    if (fb) fb.innerHTML = '<div class="dar-fb-soft">لا بأس — جرّب اختياراً آخر.</div>';
  }
}
/* --- 6. تلقين وتكرار --- */
let darRepeatState = null;
function darExBuildRepeat(d, ayahs) {
  const disp = darDisplayAyahs(d);
  const list = disp.ayahs;
  return '<p>اختر عدد التكرار، ثم اضغط «ابدأ التكرار» — تُعاد كل آية بصوت ' + darEsc(darReciterName()) + ':</p>' +
    '<div class="row"><label>تكرار كل آية: <select id="darRepeatCount"><option value="3">×3</option><option value="5">×5</option><option value="10">×10</option></select></label>' +
    '<label>من آية: <select id="darRepeatFrom">' + list.map(function (a) { return '<option value="' + a.n + '">' + a.n + '</option>'; }).join('') + '</select></label>' +
    '<label>إلى آية: <select id="darRepeatTo">' + list.map(function (a) { return '<option value="' + a.n + '"' + (a.n === list[list.length - 1].n ? ' selected' : '') + '>' + a.n + '</option>'; }).join('') + '</select></label></div>' +
    '<div class="row"><button class="dar-btn dar-btn-primary" id="darRepeatStart" onclick="darExRepeatStart()">▶ ابدأ التكرار</button>' +
    '<button class="dar-btn" onclick="darExRepeatStop()">⏹ إيقاف</button></div>' +
    '<div class="dar-ayahs">' + list.map(function (a) {
      return '<div class="dar-ayah-card" id="rep-ayah-' + a.n + '"><div class="dar-ayah-head"><span class="dar-ayah-num">' + a.n + '</span>' +
        (a.audio ? '<button class="dar-play-btn" data-audio="' + darEsc(a.audio) + '" onclick="playQuranAyah(this)">▶ استمع</button>' : '') + '</div>' +
        '<div class="dar-ayah-text">' + darEsc(a.text) + ' <span class="dar-ayah-end">۝ ' + darArNum(a.n) + '</span></div></div>';
    }).join('') + '</div><div class="dar-game-feedback" id="darExFeedback"></div>';
}
function darExRepeatStart() {
  const d = DARQ.surahCache[darSurahCacheKey(darExSurah)];
  if (!d) return;
  const times = Number((document.getElementById('darRepeatCount') || {}).value || 3);
  const from = Number((document.getElementById('darRepeatFrom') || {}).value || 1);
  const to = Number((document.getElementById('darRepeatTo') || {}).value || d.ayahs.length);
  const list = darDisplayAyahs(d).ayahs.filter(function (a) { return a.n >= Math.min(from, to) && a.n <= Math.max(from, to) && a.audio; });
  if (!list.length) return;
  darRepeatState = { list: list, idx: 0, rep: 0, times: times };
  const fb = document.getElementById('darExFeedback');
  if (fb) fb.innerHTML = '<div class="dar-fb-soft">🔁 تكرار الآيات ' + list[0].n + '–' + list[list.length - 1].n + '، كل آية ×' + times + '…</div>';
  darRepeatNext();
}
function darRepeatNext() {
  if (!darRepeatState) return;
  const st = darRepeatState;
  if (st.idx >= st.list.length) {
    darRepeatState = null;
    const fb = document.getElementById('darExFeedback');
    if (fb) fb.innerHTML = '<div class="dar-fb-good">👏 انتهى التكرار — أحسنت! كرّرها بنفسك الآن.</div>';
    return;
  }
  const a = st.list[st.idx];
  const card = document.getElementById('rep-ayah-' + a.n);
  darPlayUrl(a.audio, card);
  st.rep++;
  if (st.rep >= st.times) { st.rep = 0; st.idx++; }
}
function darExRepeatStop() {
  darRepeatState = null;
  darStopAudio();
  const fb = document.getElementById('darExFeedback');
  if (fb) fb.innerHTML = '';
}
/* --- 7. كلمة كلمة (معنى الآية من التفسير الميسر — لا معاني مخترعة للكلمات) --- */
function darExBuildWord(d, ayahs) {
  const a = ayahs[Math.floor(Math.random() * ayahs.length)];
  const words = darWords(a.text);
  darExState = { kind: 'word', surah: d.n, ayah: a.n };
  window.__darEx = { kind: 'word', surah: d.n, ayah: a.n, correct: a.text, source: a.text };
  return '<p>اضغط على أي كلمة في الآية رقم ' + a.n + ' لتقرأ <b>معنى الآية</b> من التفسير الميسر (المعنى للآية كاملة — لا نخترع معنى لكل كلمة):</p>' +
    '<div class="dar-ex-ayah">' + words.map(function (w) {
      return '<button class="dar-word-btn" onclick="darExShowTafsir()">' + darEsc(w) + '</button>';
    }).join(' ') + ' <span class="dar-ayah-end">۝ ' + darArNum(a.n) + '</span></div>' +
    '<div id="darWordTafsir"></div>';
}
function darExShowTafsir() {
  const st = darExState;
  if (!st || st.kind !== 'word') return;
  const d = DARQ.surahCache[darSurahCacheKey(st.surah)];
  const box = document.getElementById('darWordTafsir');
  if (!d || !box) return;
  const a = d.ayahs.find(function (x) { return x.n === st.ayah; });
  if (!a) return;
  box.innerHTML = a.tafsir
    ? '<div class="dar-tafsir-show"><b>📘 معنى الآية ' + st.ayah + ' (التفسير الميسر):</b><p>' + darEsc(a.tafsir) + '</p></div>'
    : '<div class="dar-hint">لا يوجد تفسير محفوظ لهذه الآية — لا نخترع معنى.</div>';
}
/* --- 8. خريطة الحفظ --- */
function darExBuildMap() {
  const l = darGetLesson();
  const due = darDueToday();
  const dueBySurah = {};
  due.forEach(function (x) { dueBySurah[x.surah] = (dueBySurah[x.surah] || 0) + 1; });
  let streak = 0;
  try { streak = (typeof currentStreak === 'function') ? currentStreak() : 0; } catch (e) {}
  darExState = { kind: 'map' };
  window.__darEx = { kind: 'map', done: l.done.slice(), due: due.length, streak: streak };
  let h = '<p>🔥 سلسلة أيامك: <b>' + streak + '</b> • سور مكتملة: <b>' + l.done.length + '</b> • آيات مستحقة للمراجعة اليوم: <b>' + due.length + '</b></p>';
  h += '<p>اضغط على أي سورة لمراجعتها — النجمة ⭐ تعني أنك أنهيت درسها:</p>';
  h += '<div class="dar-map-grid">';
  for (let n = 114; n >= 78; n--) {
    const s = DAR_SURAHS[n - 1];
    const isDone = l.done.indexOf(n) !== -1;
    const dueN = dueBySurah[n] || 0;
    h += '<button class="dar-map-card' + (isDone ? ' done' : '') + '" onclick="darOpenSurah(' + n + ')">' +
      '<span class="dar-map-star">' + (isDone ? '⭐' : '○') + '</span>' +
      '<span class="dar-map-name">' + darEsc(s.name.replace(/سُورَةُ /g, '')) + '</span>' +
      '<span class="dar-map-meta">' + s.ayahs + ' آية' + (dueN ? ' • ' + dueN + ' مستحقة' : '') + '</span></button>';
  }
  h += '</div>';
  return h;
}
/* --- 9. المتشابهات --- */
function darExBuildSimilar(d, ayahs) {
  const normWords = function (t) { return darWords(darStripDia(t)).map(function (w) { return w.replace(/[أإآٱ]/g, 'ا'); }); };
  let pair = null;
  for (let i = 0; i < ayahs.length && !pair; i++) {
    for (let j = i + 1; j < ayahs.length && !pair; j++) {
      const wi = normWords(ayahs[i].text), wj = normWords(ayahs[j].text);
      for (let k = 0; k + 1 < wi.length && !pair; k++) {
        for (let m = 0; m + 1 < wj.length && !pair; m++) {
          if (wi[k] === wj[m] && wi[k + 1] === wj[m + 1] && wi.length > k + 2 && wj.length > m + 2 && wi[k + 2] !== wj[m + 2]) {
            // display the ORIGINAL (verbatim) words, not the normalized comparison form
            const origI = darWords(ayahs[i].text), origJ = darWords(ayahs[j].text);
            pair = { a: ayahs[i], b: ayahs[j], shared: [origI[k], origI[k + 1]], nextA: origI[k + 2], nextB: origJ[m + 2] };
          }
        }
      }
    }
  }
  if (!pair) return '<p class="dar-hint">لا توجد آيات متشابهة في هذه السورة — جرّب سورة أطول (مثل النبأ أو الملك).</p>';
  const pool = [];
  ayahs.forEach(function (x) { darWords(x.text).forEach(function (w) { if (w !== pair.nextA && w !== pair.nextB && pool.indexOf(w) === -1) pool.push(w); }); });
  const third = pool.length ? pool[Math.floor(Math.random() * pool.length)] : pair.nextB;
  const choices = darShuffle([pair.nextA, pair.nextB, third]);
  darExState = { kind: 'similar', surah: d.n, ayah: pair.a.n, correct: pair.nextA };
  window.__darEx = { kind: 'similar', surah: d.n, ayah: pair.a.n, correct: pair.nextA, source: pair.a.text, shared: pair.shared };
  return '<p>الآيتان متشابهتان في البداية — ما الكلمة التالية في <b>الآية رقم ' + pair.a.n + '</b>؟</p>' +
    '<div class="dar-ex-ayah">' + darEsc(pair.shared.join(' ')) + ' … ؟</div>' +
    '<div class="dar-hint">الآية الأخرى المتشابهة هي رقم ' + pair.b.n + ' — انتبه للفرق بينهما.</div>' +
    '<div class="dar-ex-choices">' + choices.map(function (c) {
      return '<button class="dar-choice" onclick="darExAnswerSimilar(this)">' + darEsc(c) + '</button>';
    }).join('') + '</div><div class="dar-game-feedback" id="darExFeedback"></div>';
}
function darExAnswerSimilar(btn) {
  const fb = document.getElementById('darExFeedback');
  const st = darExState;
  if (!st || st.kind !== 'similar') return;
  if (btn.textContent.trim() === st.correct) {
    btn.classList.add('correct');
    document.querySelectorAll('#darExArea .dar-choice').forEach(function (b) { b.disabled = true; });
    if (fb) fb.innerHTML = '<div class="dar-fb-good">👏 أحسنت — ميّزت بين الآيتين المتشابهتين!</div>';
  } else {
    btn.classList.add('wrong');
    btn.disabled = true;
    if (fb) fb.innerHTML = '<div class="dar-fb-soft">لا بأس — هذه هي فائدة التدريب على المتشابهات. حاول تاني.</div>';
  }
}
/* --- 10. الكلمات الصعبة --- */
function darExBuildHard(d, ayahs) {
  const list = darHardWords();
  if (!list.length) {
    return '<p class="dar-hint">💪 لا توجد كلمات صعبة بعد — الكلمات التي تخطئ فيها في تمرين «أكمل الآية» ستظهر هنا، وتعود حتى تثبت (أجب عنها صح مرتين).</p>';
  }
  const w = list[0];
  const a = ayahs.find(function (x) { return x.n === w.ayah; });
  if (!a || darWords(a.text).indexOf(w.word) === -1) {
    return '<p class="dar-hint">الكلمة الصعبة من سورة أخرى — افتح سورة ' + darEsc(darSurahBare(DAR_SURAHS[w.surah - 1].name)) + ' من المصحف وتدرّب عليها هناك.</p>' +
      '<button class="dar-btn" onclick="darOpenSurah(' + w.surah + ')">📖 افتح سورة ' + darEsc(darSurahBare(DAR_SURAHS[w.surah - 1].name)) + '</button>';
  }
  const words = darWords(a.text);
  const wi = words.indexOf(w.word);
  const pool = [];
  ayahs.forEach(function (x) { darWords(x.text).forEach(function (ww) { if (ww !== w.word && pool.indexOf(ww) === -1) pool.push(ww); }); });
  const choices = darShuffle([w.word].concat(darShuffle(pool).slice(0, 2)));
  darExState = { kind: 'hard', surah: d.n, ayah: a.n, word: w.word, choices: choices };
  window.__darEx = { kind: 'hard', surah: d.n, ayah: a.n, correct: w.word, source: a.text, choices: choices };
  const shown = words.map(function (x, i) { return i === wi ? '«_____»' : darEsc(x); }).join(' ');
  return '<p>كلمة صعبة — أكمل الآية رقم ' + a.n + ' (أجب صح مرتين لتثبت):</p>' +
    '<div class="dar-ex-ayah">' + shown + ' <span class="dar-ayah-end">۝ ' + darArNum(a.n) + '</span></div>' +
    '<div class="dar-ex-choices">' + choices.map(function (c) {
      return '<button class="dar-choice" onclick="darExAnswerComplete(this)">' + darEsc(c) + '</button>';
    }).join('') + '</div><div class="dar-game-feedback" id="darExFeedback"></div>';
}

/* ---------- init ---------- */
function darInit() {
  darRenderQuran();
  darRenderTajweed();
  darRenderHadith();
  darEnsureHome();
}
/* ============================================================
   P6 — «اسأل المعلم» يجيب من نصوص التطبيق المعتمدة فقط (RAG محلي)
   ------------------------------------------------------------
   التطبيق static بلا خادم، فالاسترجاع كله client-side:
   - نصوص مضمّنة: متن تحفة الأطفال + شروح القواعد + أمثلتها (DAR_MATN)،
     أسئلة الاختبار وإجاباتها (DAR_QUIZ)، مواقف السلوكيات وأدلتها
     الموثقة (data/manners.json — تُحمَّل عند الحاجة).
   - نصوص تُجلَب عند الطلب: سورة يسمّيها السؤال (quran-uthmani +
     التفسير الميسر عبر darFetchSurah)، وكتاب حديث يسمّيه السؤال
     (أول 10 أحاديث من الكتاب عبر darFetchHadith).
   - المطابقة: كلمات مفتاحية بعد تطبيع عربي، مع وزن IDF. يطابق المقطع
     إذا شارك السؤال (أ) كلمة «محددة» (تظهر في ≤ 5 مقاطع)، أو (ب) كلمتين
     على الأقل إحداهما مصطلح تجويد. كلمة عامة وحدها (مثل «حكم») لا تكفي.
   - حارس الفتوى: سؤال فيه «يجوز/حلال/حرام/ما حكم» ولا يحمل أي مصطلح
     تجويد ⇒ رفض مباشر بلا استرجاع ولا استدعاء للنموذج. التطبيق لا يفتي.
   - صفر مقاطع ⇒ الرفض مباشرة بلا استدعاء النموذج أصلاً:
     «لا أعلم — لا يوجد مصدر معتمد عندي لهذا السؤال».
   - لا TTS هنا أبداً — الشات نص فقط.
   ============================================================ */
const DAR_RAG_NO_SOURCE = 'لا أعلم — لا يوجد مصدر معتمد عندي لهذا السؤال';
const DAR_RAG_MAX_PASSAGES = 3;

/* أسماء السور في DAR_SURAHS (ومن API المصحف) تبدأ بـ «سُورَةُ» — عند بناء
   عبارة «سورة X» نزيل البادئة أولاً حتى لا تتضاعف الكلمة. */
function darSurahBare(name) { return String(name || '').replace(/سُورَةُ /g, '').trim(); }
function darRagNorm(s) {
  return String(s || '')
    .replace(/[\u064b-\u0652\u0670\u0640\u0654\u0655]/g, '')
    .replace(/[ٱأإآ]/g, 'ا').replace(/ة/g, 'ه').replace(/ى/g, 'ي')
    .replace(/ؤ/g, 'و').replace(/ئ/g, 'ي')
    .replace(/[^ء-ي0-9\s]/g, ' ')
    .replace(/\s+/g, ' ').trim();
}
const DAR_RAG_STOP = new Set(('في من الي على عن مع بعد قبل عند بين تحت فوق ما هو هي ان إن لا لم لن هل كيف متى اين لماذا هذا هذه ذلك تلك الذي التي الذين كان يكون كنت او ثم قد لقد انما لكن بل حتى اذا لو كل اي بعض غير نحو دون منذ حيث اذ اما ولا سورة سوره ايه ايات اية آية معنى يعني اشرح شرح اسال اسأل سؤال اريد عايز ممكن لو سمحت من فضلك يا اول عدد اكتر اكثر اقل كمل وضح تاني كتير جدا اوي').split(' ')); // + كلمات المتابعة العامة («اشرح أكتر»، «وضح»، «كمل») حتى يعيد السؤال بلا محتوى استخدام آخر سؤال له محتوى
/* كلمات عامة في التجويد — وزنها محدود مهما قلّ ظهورها في الفهرس الصغير،
   حتى لا تتفوق على الكلمة المحددة (مثل «الإخفاء») في الترتيب. */
const DAR_RAG_GENERIC = new Set(('حكم احكام النون التنوين المد الميم اللام').split(' '));
const DAR_RAG_SYN = { 'ابر': 'بر', 'والدي': 'الوالدين', 'والداي': 'الوالدين', 'ابي': 'بابا', 'امي': 'ماما' };
function darRagTokens(s) {
  return darRagNorm(s).split(' ').filter(function (w) { return w && w.length > 1 && !DAR_RAG_STOP.has(w); })
    .map(function (w) { return DAR_RAG_SYN[w] || w; });
}
/* مصطلحات التجويد/التلاوة — وجود أحدها في السؤال يعني أن السؤال عن
   التجويد لا عن فتوى، فيُسمح باسترجاع قواعد التجويد. */
const DAR_RAG_TAJWEED = new Set(('النون التنوين المد الاخفاء الادغام الاقلاب الاظهار الميم اللام الغنه التجويد الوقف الابتداء مخارج صفات الحروف السكون الشده المشدد المثقل المخفف المتصل المنفصل العارض اللازم الطبيعي البدل العوض الصله اللين الروم الاشمام الكلمي الحرفي المثلان المتقاربان المتجانسان الكبير الصغير القمريه الشمسيه الحلقي الحقيقي الشفوي المدود الاحكام التلاوه الترتيل الحفظ التسميع المدود').split(' '));
/* محفزات الفتوى — مع غياب أي مصطلح تجويد تعني أن السؤال فتوى/حكم شرعي. */
const DAR_RAG_FATWA = new Set(('يجوز حلال حرام فتوي افتوني افتاء حكم احكام').split(' '));
function darRagIsFatwaLike(question) {
  const toks = darRagTokens(question);
  const hasTrigger = toks.some(function (t) { return DAR_RAG_FATWA.has(t); });
  if (!hasTrigger) return false;
  return !toks.some(function (t) { return DAR_RAG_TAJWEED.has(t); });
}

/* أسماء سور لا تُستخدم في الكشف بالاسم المجرّد (كلمات شائعة في الكلام
   العادي) — هذه السور تُكتشف فقط بصيغة «سورة X» أو برقمها. */
const DAR_RAG_SURA_DENY = new Set(('الناس النساء النور الملك القمر الشمس الليل الفجر الضحي البلد التين العلق القدر البينه الزلزله العاديات القارعه التكاثر العصر الهمزه الفيل قريش الماعون الكوثر الكافرون النصر المسد الاخلاص الفلق الروم الحديد النجم الطور الجن النحل النمل العنكبوت القلم الانسان الجمعه الصف الحشر الشرح الفتح يس ص ق طه نوح').split(' '));

let DAR_RAG_INDEX = null;
function darRagSurahDisplay(n) {
  const s = DAR_SURAHS[n - 1];
  if (!s) return 'سورة ' + n;
  return 'سورة ' + darRagNorm(s.name).replace(/^سوره\s+/, '').replace(/\s+/g, ' ').trim();
}
function darRagBuildIndex(manners) {
  if (DAR_RAG_INDEX) return DAR_RAG_INDEX;
  const passages = [];
  function add(kind, text, ref) {
    const toks = darRagTokens(text);
    if (!toks.length) return;
    passages.push({ kind: kind, text: text, ref: ref, toks: toks, set: new Set(toks) });
  }
  // متن تحفة الأطفال: كل بيت مقطع بمرجعه (الباب + رقم البيت)
  add('matn', DAR_MATN.intro.map(function (v) { return v.join(' '); }).join(' — '), 'متن تحفة الأطفال — المقدمة');
  DAR_MATN.chapters.forEach(function (ch) {
    ch.verses.forEach(function (v, i) {
      add('matn', v.join(' '), 'متن تحفة الأطفال — باب ' + ch.title + ' (بيت ' + (i + 1) + ')');
    });
    ch.rules.forEach(function (r) {
      const ex = r.example ? (' مثال: ' + r.example.frag + ' — ' + (r.example.note || '')) : '';
      const sName = (r.example && r.example.surah) ? darRagSurahDisplay(r.example.surah) : '';
      const sRef = (r.example && r.example.surah) ? ('، ' + sName + ' آية ' + r.example.ayah) : '';
      add('rule', r.name + ' — ' + r.plain + ex, 'حكم ' + r.name + ' — باب ' + ch.title + sRef);
    });
  });
  DAR_MATN.khatima.forEach(function (v, i) {
    add('matn', v.join(' '), 'متن تحفة الأطفال — الخاتمة (بيت ' + (i + 1) + ')');
  });
  // أسئلة الاختبار وإجاباتها الصحيحة
  Object.keys(DAR_QUIZ).forEach(function (chId) {
    const ch = DAR_MATN.chapters.find(function (c) { return c.id === chId; });
    DAR_QUIZ[chId].forEach(function (q) {
      add('quiz', q.q + ' — الإجابة: ' + q.options[q.a], 'اختبار التجويد — باب ' + (ch ? ch.title : chId));
    });
  });
  // السلوكيات: كل موقف + دليله الموثق
  if (manners && Array.isArray(manners.situations)) {
    const gname = function (g) { return (manners.groups && manners.groups[g] && manners.groups[g].name) || g; };
    manners.situations.forEach(function (sit) {
      let ev = '';
      if (sit.evidence) ev += ' الدليل: ' + sit.evidence.text + ' (' + sit.evidence.ref + ')';
      if (sit.evidence2) ev += ' — ' + sit.evidence2.text + ' (' + sit.evidence2.ref + ')';
      add('manners', sit.title + ' — ' + sit.situation + ' ' + sit.instead + ' ' + sit.do + ' ' + sit.why + ' ' + sit.action + ev,
        'السلوكيات — ' + gname(sit.group) + ': ' + sit.title);
    });
    if (manners.namesake) {
      add('manners', manners.namesake.text, 'حديث «علم ينتفع به» — ' + manners.namesake.ref);
    }
  }
  // IDF: عدد المقاطع التي تحتوي كل كلمة
  const df = {};
  passages.forEach(function (p) { p.set.forEach(function (t) { df[t] = (df[t] || 0) + 1; }); });
  DAR_RAG_INDEX = { passages: passages, df: df };
  return DAR_RAG_INDEX;
}
function darRagWeight(df, tok) { const w = df <= 2 ? 2 : df <= 5 ? 1 : df <= 15 ? 0.5 : 0.2; return (tok && DAR_RAG_GENERIC.has(tok)) ? Math.min(w, 0.5) : w; }
function darRagScore(qToks, p, df) {
  let score = 0, specific = false, shared = 0, sharedTopic = false;
  qToks.forEach(function (t) {
    if (!p.set.has(t)) return;
    shared++;
    const w = darRagWeight(df[t] || 99, t);
    score += w;
    if (w >= 1) specific = true;
    if (DAR_RAG_TAJWEED.has(t)) sharedTopic = true;
  });
  // (أ) كلمة محددة مشتركة، أو (ب) كلمتان مشتركتان إحداهما مصطلح تجويد
  if (specific) return score;
  if (shared >= 2 && sharedTopic) return score;
  return 0;
}
function darRagFindSurah(q) {
  const nq = ' ' + darRagNorm(q) + ' ';
  const m = nq.match(/سوره?\s+(?:رقم\s+)?(\d{1,3})/);
  if (m) { const n = parseInt(m[1], 10); if (n >= 1 && n <= 114) return n; }
  for (let i = 0; i < DAR_SURAHS.length; i++) {
    const bare = darRagNorm(DAR_SURAHS[i].name).replace(/^سوره\s+/, '').trim();
    if (bare && nq.indexOf(' سوره ' + bare + ' ') >= 0) return DAR_SURAHS[i].n;
  }
  // الاسم المجرّد: فقط مع كلمة قرآنية في السؤال، واسم غير شائع وطوله ≥ 4
  const quranWords = [' ايه ', ' ايات ', ' تفسير ', ' قال الله ', ' يقول الله ', ' نزلت ', ' معني '];
  const hasQ = quranWords.some(function (w) { return nq.indexOf(w) >= 0; });
  if (!hasQ) return null;
  for (let i = 0; i < DAR_SURAHS.length; i++) {
    const bare = darRagNorm(DAR_SURAHS[i].name).replace(/^سوره\s+/, '').trim();
    if (!bare || bare.length < 4 || DAR_RAG_SURA_DENY.has(bare)) continue;
    if (nq.indexOf(' ' + bare + ' ') >= 0) return DAR_SURAHS[i].n;
  }
  return null;
}
function darRagFindBook(q) {
  const nq = ' ' + darRagNorm(q) + ' ';
  const colls = [['bukhari', 'صحيح البخاري'], ['muslim', 'صحيح مسلم']];
  for (let ci = 0; ci < colls.length; ci++) {
    const coll = colls[ci][0];
    const books = DAR_HADITH[coll].books;
    for (let i = 0; i < books.length; i++) {
      const bare = darRagNorm(books[i].name);
      if (!bare || bare.length < 3) continue;
      if (nq.indexOf(' كتاب ' + bare + ' ') >= 0) return { coll: coll, book: books[i] };
      const collName = darRagNorm(coll === 'bukhari' ? 'صحيح البخاري' : 'صحيح مسلم');
      if (nq.indexOf(' ' + collName + ' ') >= 0 && nq.indexOf(' ' + bare + ' ') >= 0) return { coll: coll, book: books[i] };
    }
  }
  return null;
}
function darRagRetrieve(question, manners) {
  if (darRagIsFatwaLike(question)) return { passages: [], namedSurah: null, namedBook: null, fatwa: true };
  const idx = darRagBuildIndex(manners);
  const qToks = darRagTokens(question);
  const scored = [];
  idx.passages.forEach(function (p) {
    const s = darRagScore(qToks, p, idx.df);
    if (s > 0) scored.push({ kind: p.kind, text: p.text, ref: p.ref, score: s });
  });
  scored.sort(function (a, b) { return b.score - a.score; });
  return { passages: scored.slice(0, DAR_RAG_MAX_PASSAGES), namedSurah: darRagFindSurah(question), namedBook: darRagFindBook(question), fatwa: false };
}
async function darRagFetchSurahPassages(n, qToks) {
  const d = await darFetchSurah(n);
  const out = [];
  const sName = darRagSurahDisplay(n);
  d.ayahs.forEach(function (a) {
    const toks = new Set(darRagTokens(a.text + ' ' + (a.tafsir || '')));
    let shared = 0;
    qToks.forEach(function (t) { if (toks.has(t)) shared++; });
    if (shared >= 2 || (shared === 1 && qToks.length === 1)) {
      const taf = (a.tafsir || '').slice(0, 300);
      out.push({ kind: 'ayah', score: 2 + shared,
        text: a.text + (taf ? ' — التفسير الميسر: ' + taf : ''),
        ref: sName + ' — آية ' + a.n });
    }
  });
  out.sort(function (a, b) { return b.score - a.score; });
  return out.slice(0, DAR_RAG_MAX_PASSAGES);
}
async function darRagFetchBookPassages(found, qToks) {
  const coll = found.coll, book = found.book;
  const jobs = [];
  for (let n = book.first; n <= Math.min(book.last, book.first + 9); n++) jobs.push(darFetchHadith(coll, n).catch(function () { return null; }));
  const hs = await Promise.all(jobs);
  const out = [];
  hs.forEach(function (h) {
    if (!h || !h.text) return;
    const toks = new Set(darRagTokens(h.text));
    let shared = 0;
    qToks.forEach(function (t) { if (toks.has(t)) shared++; });
    if (shared < 1) return;
    const num = (coll === 'muslim' && h.arabicnumber) ? Math.floor(Number(h.arabicnumber)) : h.hadithnumber;
    const grade = (h.grades && h.grades.length) ? h.grades[0].grade : 'صحيح — ' + DAR_HADITH[coll].collection + ' (صحة المجموعة)';
    out.push({ kind: 'hadith', score: 1 + shared,
      text: h.text + ' — ' + grade,
      ref: DAR_HADITH[coll].collection + ' — كتاب ' + book.name + '، حديث رقم ' + num });
  });
  out.sort(function (a, b) { return b.score - a.score; });
  return out.slice(0, DAR_RAG_MAX_PASSAGES);
}
async function darAnswerFromSources(question) {
  if (darRagIsFatwaLike(question)) return { passages: [], refusal: true, fatwa: true };
  let manners = null;
  try { manners = await darFetchManners(); } catch (e) { manners = null; }
  const r = darRagRetrieve(question, manners);
  const qToks = darRagTokens(question);
  let extra = [];
  if (r.namedSurah) {
    try { extra = extra.concat(await darRagFetchSurahPassages(r.namedSurah, qToks)); } catch (e) { /* بلا سورة — يكفي الفهرس المضمّن */ }
  }
  if (r.namedBook) {
    try { extra = extra.concat(await darRagFetchBookPassages(r.namedBook, qToks)); } catch (e) { /* بلا كتاب — يكفي الفهرس المضمّن */ }
  }
  const all = r.passages.concat(extra).sort(function (a, b) { return b.score - a.score; }).slice(0, DAR_RAG_MAX_PASSAGES);
  if (!all.length) return { passages: [], refusal: true, fatwa: false };
  return { passages: all, refusal: false, fatwa: false };
}
function darRagSystemBlock(passages) {
  const lines = passages.map(function (p, i) {
    return '[' + (i + 1) + '] (' + p.ref + '): ' + p.text;
  });
  return 'المصادر المعتمدة الوحيدة لهذا السؤال — من نصوص التطبيق نفسه، لا تستخدم أي مصدر آخر ولا ذاكرتك:\n' + lines.join('\n') +
    '\nقواعد صارمة:\n- أجب ONLY من المقاطع أعلاه، واذكر مرجع كل معلومة (رقم المصدر بين قوسين) في إجابتك.\n- إن لم تجد في المقاطع ما يجيب عن السؤال، قل حرفياً: «' + DAR_RAG_NO_SOURCE + '» ولا تضف شيئاً.\n- لا تنقل أي آية أو حديث أو بيت متن من ذاكرتك — فقط المقاطع أعلاه.\n- لا تفتِ ولا تستنتج أحكاماً شرعية من عندك.';
}

document.addEventListener('DOMContentLoaded', function () {
  // the Quran tab content is rendered when the app boots (sections exist in HTML)
  if (document.getElementById('quranContent')) darInit();
});

/* ---------- sub-navigation (shim — sections are top-level tabs now) ---------- */
function darShowSub(name) {
  const map = { mushaf: 'quran', tajweed: 'tajweed', hadith: 'hadith', manners: 'manners', exercises: 'exercises', home: 'home' };
  darSwitchTab(map[name] || 'quran');
}
